test "x86_64 gp forms vs LLVM (400..800)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    const x = @import("x86_64/assembler.zig");
    const gp = @import("x86_64/gp.zig");
    var fails: u32 = 0;
    fails += check(&.{ 0x41, 0x0F, 0xBA, 0xE1, 0x7F }, .bt, .{ gp.r32(.r9), @as(i64, 127) }, "bt r9d, 127");
    fails += check(&.{ 0x0F, 0xBA, 0xE6, 0x7F }, .bt, .{ gp.r32(.rsi), @as(i64, 127) }, "bt esi, 127");
    fails += check(&.{ 0x48, 0x0F, 0xBA, 0x64, 0x48, 0x10, 0x7F }, .bt, .{ gp.qword(x.ptrIdx(.rax, .rcx, .x2, 16)), @as(i64, 127) }, "bt qword ptr [rax+rcx*2+16], 127");
    fails += check(&.{ 0x49, 0x0F, 0xBA, 0x65, 0x00, 0x7F }, .bt, .{ gp.qword(x.ptr(.r13, 0)), @as(i64, 127) }, "bt qword ptr [r13], 127");
    fails += check(&.{ 0x4B, 0x0F, 0xBA, 0xA4, 0xCC, 0x00, 0xF0, 0xFF, 0xFF, 0x7F }, .bt, .{ gp.qword(x.ptrIdx(.r12, .r9, .x8, -0x1000)), @as(i64, 127) }, "bt qword ptr [r12+r9*8-4096], 127");
    fails += check(&.{ 0x48, 0x0F, 0xBA, 0x25, 0x00, 0x01, 0x00, 0x00, 0x7F }, .bt, .{ gp.rip(0x100, .q), @as(i64, 127) }, "bt qword ptr [rip+0x100], 127");
    fails += check(&.{ 0x48, 0x0F, 0xBA, 0xE1, 0x7F }, .bt, .{ gp.r64(.rcx), @as(i64, 127) }, "bt rcx, 127");
    fails += check(&.{ 0x49, 0x0F, 0xBA, 0xE1, 0x7F }, .bt, .{ gp.r64(.r9), @as(i64, 127) }, "bt r9, 127");
    fails += check(&.{ 0x48, 0x0F, 0xBA, 0xE6, 0x7F }, .bt, .{ gp.r64(.rsi), @as(i64, 127) }, "bt rsi, 127");
    fails += check(&.{ 0x66, 0x0F, 0xBB, 0x4C, 0x48, 0x10 }, .btc, .{ gp.word(x.ptrIdx(.rax, .rcx, .x2, 16)), gp.r16(.rcx) }, "btc word ptr [rax+rcx*2+16], cx");
    fails += check(&.{ 0x66, 0x45, 0x0F, 0xBB, 0x4D, 0x00 }, .btc, .{ gp.word(x.ptr(.r13, 0)), gp.r16(.r9) }, "btc word ptr [r13], r9w");
    fails += check(&.{ 0x66, 0x43, 0x0F, 0xBB, 0xB4, 0xCC, 0x00, 0xF0, 0xFF, 0xFF }, .btc, .{ gp.word(x.ptrIdx(.r12, .r9, .x8, -0x1000)), gp.r16(.rsi) }, "btc word ptr [r12+r9*8-4096], si");
