test "x86_64 gp forms vs LLVM (800..1200)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    const x = @import("x86_64/assembler.zig");
    const gp = @import("x86_64/gp.zig");
    var fails: u32 = 0;
    fails += check(&.{ 0x0F, 0x45, 0xF7 }, .cmovnz, .{ gp.r32(.rsi), gp.r32(.rdi) }, "cmovnz esi, edi");
    fails += check(&.{ 0x48, 0x0F, 0x45, 0x4C, 0x48, 0x10 }, .cmovnz, .{ gp.r64(.rcx), gp.qword(x.ptrIdx(.rax, .rcx, .x2, 16)) }, "cmovnz rcx, qword ptr [rax+rcx*2+16]");
    fails += check(&.{ 0x4D, 0x0F, 0x45, 0x4D, 0x00 }, .cmovnz, .{ gp.r64(.r9), gp.qword(x.ptr(.r13, 0)) }, "cmovnz r9, qword ptr [r13]");
