    _ = &x;
    try std.testing.expectEqual(@as(u32, 0), fails);
}

test "x86_64 gp forms vs LLVM (1200..1600)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    const x = @import("x86_64/assembler.zig");
    const gp = @import("x86_64/gp.zig");
    var fails: u32 = 0;
    fails += check(&.{ 0x66, 0x41, 0xFF, 0x45, 0x00 }, .inc, .{ gp.word(x.ptr(.r13, 0)) }, "inc word ptr [r13]");
    fails += check(&.{ 0x66, 0x43, 0xFF, 0x84, 0xCC, 0x00, 0xF0, 0xFF, 0xFF }, .inc, .{ gp.word(x.ptrIdx(.r12, .r9, .x8, -0x1000)) }, "inc word ptr [r12+r9*8-4096]");
    fails += check(&.{ 0x66, 0xFF, 0x05, 0x00, 0x01, 0x00, 0x00 }, .inc, .{ gp.rip(0x100, .w) }, "inc word ptr [rip+0x100]");
    fails += check(&.{ 0x66, 0xFF, 0xC1 }, .inc, .{ gp.r16(.rcx) }, "inc cx");
    fails += check(&.{ 0x66, 0x41, 0xFF, 0xC1 }, .inc, .{ gp.r16(.r9) }, "inc r9w");
    fails += check(&.{ 0x66, 0xFF, 0xC6 }, .inc, .{ gp.r16(.rsi) }, "inc si");
    fails += check(&.{ 0xFF, 0x44, 0x48, 0x10 }, .inc, .{ gp.dword(x.ptrIdx(.rax, .rcx, .x2, 16)) }, "inc dword ptr [rax+rcx*2+16]");
    fails += check(&.{ 0x41, 0xFF, 0x45, 0x00 }, .inc, .{ gp.dword(x.ptr(.r13, 0)) }, "inc dword ptr [r13]");
    fails += check(&.{ 0x43, 0xFF, 0x84, 0xCC, 0x00, 0xF0, 0xFF, 0xFF }, .inc, .{ gp.dword(x.ptrIdx(.r12, .r9, .x8, -0x1000)) }, "inc dword ptr [r12+r9*8-4096]");
    fails += check(&.{ 0xFF, 0x05, 0x00, 0x01, 0x00, 0x00 }, .inc, .{ gp.rip(0x100, .d) }, "inc dword ptr [rip+0x100]");
    fails += check(&.{ 0xFF, 0xC1 }, .inc, .{ gp.r32(.rcx) }, "inc ecx");
    fails += check(&.{ 0x41, 0xFF, 0xC1 }, .inc, .{ gp.r32(.r9) }, "inc r9d");
    fails += check(&.{ 0xFF, 0xC6 }, .inc, .{ gp.r32(.rsi) }, "inc esi");
    fails += check(&.{ 0x48, 0xFF, 0x44, 0x48, 0x10 }, .inc, .{ gp.qword(x.ptrIdx(.rax, .rcx, .x2, 16)) }, "inc qword ptr [rax+rcx*2+16]");
    fails += check(&.{ 0x49, 0xFF, 0x45, 0x00 }, .inc, .{ gp.qword(x.ptr(.r13, 0)) }, "inc qword ptr [r13]");
    fails += check(&.{ 0x4B, 0xFF, 0x84, 0xCC, 0x00, 0xF0, 0xFF, 0xFF }, .inc, .{ gp.qword(x.ptrIdx(.r12, .r9, .x8, -0x1000)) }, "inc qword ptr [r12+r9*8-4096]");
    fails += check(&.{ 0x48, 0xFF, 0x05, 0x00, 0x01, 0x00, 0x00 }, .inc, .{ gp.rip(0x100, .q) }, "inc qword ptr [rip+0x100]");
    fails += check(&.{ 0x48, 0xFF, 0xC1 }, .inc, .{ gp.r64(.rcx) }, "inc rcx");
    fails += check(&.{ 0x49, 0xFF, 0xC1 }, .inc, .{ gp.r64(.r9) }, "inc r9");
    fails += check(&.{ 0x48, 0xFF, 0xC6 }, .inc, .{ gp.r64(.rsi) }, "inc rsi");
    fails += check(&.{ 0xFE, 0x44, 0x48, 0x10 }, .inc, .{ gp.byte(x.ptrIdx(.rax, .rcx, .x2, 16)) }, "inc byte ptr [rax+rcx*2+16]");
    fails += check(&.{ 0x41, 0xFE, 0x45, 0x00 }, .inc, .{ gp.byte(x.ptr(.r13, 0)) }, "inc byte ptr [r13]");
    fails += check(&.{ 0x43, 0xFE, 0x84, 0xCC, 0x00, 0xF0, 0xFF, 0xFF }, .inc, .{ gp.byte(x.ptrIdx(.r12, .r9, .x8, -0x1000)) }, "inc byte ptr [r12+r9*8-4096]");
    fails += check(&.{ 0xFE, 0x05, 0x00, 0x01, 0x00, 0x00 }, .inc, .{ gp.rip(0x100, .b) }, "inc byte ptr [rip+0x100]");
    fails += check(&.{ 0xFE, 0xC1 }, .inc, .{ gp.r8(.rcx) }, "inc cl");
