    fails += check(&.{ 0x66, 0x0F, 0x02, 0x4C, 0x48, 0x10 }, .lar, .{ gp.r16(.rcx), gp.word(x.ptrIdx(.rax, .rcx, .x2, 16)) }, "lar cx, word ptr [rax+rcx*2+16]");
    fails += check(&.{ 0x66, 0x45, 0x0F, 0x02, 0x4D, 0x00 }, .lar, .{ gp.r16(.r9), gp.word(x.ptr(.r13, 0)) }, "lar r9w, word ptr [r13]");
    fails += check(&.{ 0x66, 0x43, 0x0F, 0x02, 0xB4, 0xCC, 0x00, 0xF0, 0xFF, 0xFF }, .lar, .{ gp.r16(.rsi), gp.word(x.ptrIdx(.r12, .r9, .x8, -0x1000)) }, "lar si, word ptr [r12+r9*8-4096]");
    fails += check(&.{ 0x66, 0x0F, 0x02, 0x0D, 0x00, 0x01, 0x00, 0x00 }, .lar, .{ gp.r16(.rcx), gp.rip(0x100, .w) }, "lar cx, word ptr [rip+0x100]");
