    fails += check(&.{ 0x0F, 0x02, 0x4C, 0x48, 0x10 }, .lar, .{ gp.r32(.rcx), gp.word(x.ptrIdx(.rax, .rcx, .x2, 16)) }, "lar ecx, word ptr [rax+rcx*2+16]");
    fails += check(&.{ 0x45, 0x0F, 0x02, 0x4D, 0x00 }, .lar, .{ gp.r32(.r9), gp.word(x.ptr(.r13, 0)) }, "lar r9d, word ptr [r13]");
