    fails += check(&.{ 0x48, 0x0F, 0x1F, 0x44, 0x48, 0x10 }, .nop, .{ gp.qword(x.ptrIdx(.rax, .rcx, .x2, 16)) }, "nop qword ptr [rax+rcx*2+16]");
    fails += check(&.{ 0x49, 0x0F, 0x1F, 0x45, 0x00 }, .nop, .{ gp.qword(x.ptr(.r13, 0)) }, "nop qword ptr [r13]");
    fails += check(&.{ 0x4B, 0x0F, 0x1F, 0x84, 0xCC, 0x00, 0xF0, 0xFF, 0xFF }, .nop, .{ gp.qword(x.ptrIdx(.r12, .r9, .x8, -0x1000)) }, "nop qword ptr [r12+r9*8-4096]");
