    fails += check(&.{ 0x48, 0x0F, 0x1F, 0xC1 }, .nop, .{ gp.r64(.rcx) }, "nop rcx");
    fails += check(&.{ 0x49, 0x0F, 0x1F, 0xC1 }, .nop, .{ gp.r64(.r9) }, "nop r9");
    fails += check(&.{ 0x48, 0x0F, 0x1F, 0xC6 }, .nop, .{ gp.r64(.rsi) }, "nop rsi");
    fails += check(&.{ 0x66, 0x0F, 0x1F, 0x44, 0x48, 0x10 }, .nop, .{ gp.word(x.ptrIdx(.rax, .rcx, .x2, 16)) }, "nop word ptr [rax+rcx*2+16]");
    fails += check(&.{ 0x66, 0x41, 0x0F, 0x1F, 0x45, 0x00 }, .nop, .{ gp.word(x.ptr(.r13, 0)) }, "nop word ptr [r13]");
    fails += check(&.{ 0x66, 0x43, 0x0F, 0x1F, 0x84, 0xCC, 0x00, 0xF0, 0xFF, 0xFF }, .nop, .{ gp.word(x.ptrIdx(.r12, .r9, .x8, -0x1000)) }, "nop word ptr [r12+r9*8-4096]");
    fails += check(&.{ 0x66, 0x0F, 0x1F, 0x05, 0x00, 0x01, 0x00, 0x00 }, .nop, .{ gp.rip(0x100, .w) }, "nop word ptr [rip+0x100]");
    fails += check(&.{ 0x66, 0x0F, 0x1F, 0xC1 }, .nop, .{ gp.r16(.rcx) }, "nop cx");
    fails += check(&.{ 0x66, 0x41, 0x0F, 0x1F, 0xC1 }, .nop, .{ gp.r16(.r9) }, "nop r9w");
    fails += check(&.{ 0x66, 0x0F, 0x1F, 0xC6 }, .nop, .{ gp.r16(.rsi) }, "nop si");
    fails += check(&.{ 0x66, 0xF7, 0x54, 0x48, 0x10 }, .not, .{ gp.word(x.ptrIdx(.rax, .rcx, .x2, 16)) }, "not word ptr [rax+rcx*2+16]");
    _ = &x;
    try std.testing.expectEqual(@as(u32, 0), fails);
}

test "x86_64 gp forms vs LLVM (1600..2000)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    const x = @import("x86_64/assembler.zig");
    const gp = @import("x86_64/gp.zig");
    var fails: u32 = 0;
    fails += check(&.{ 0x66, 0x41, 0xF7, 0x55, 0x00 }, .not, .{ gp.word(x.ptr(.r13, 0)) }, "not word ptr [r13]");
    fails += check(&.{ 0x66, 0x43, 0xF7, 0x94, 0xCC, 0x00, 0xF0, 0xFF, 0xFF }, .not, .{ gp.word(x.ptrIdx(.r12, .r9, .x8, -0x1000)) }, "not word ptr [r12+r9*8-4096]");
    fails += check(&.{ 0x66, 0xF7, 0x15, 0x00, 0x01, 0x00, 0x00 }, .not, .{ gp.rip(0x100, .w) }, "not word ptr [rip+0x100]");
    fails += check(&.{ 0x66, 0xF7, 0xD1 }, .not, .{ gp.r16(.rcx) }, "not cx");
    fails += check(&.{ 0x66, 0x41, 0xF7, 0xD1 }, .not, .{ gp.r16(.r9) }, "not r9w");
    fails += check(&.{ 0x66, 0xF7, 0xD6 }, .not, .{ gp.r16(.rsi) }, "not si");
