test "x86_64 gp forms vs LLVM (2000..2400)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    const x = @import("x86_64/assembler.zig");
    const gp = @import("x86_64/gp.zig");
    var fails: u32 = 0;
    fails += check(&.{ 0xF3, 0x0F, 0xAE, 0xC1 }, .rdfsbase, .{ gp.r32(.rcx) }, "rdfsbase ecx");
    fails += check(&.{ 0xF3, 0x41, 0x0F, 0xAE, 0xC1 }, .rdfsbase, .{ gp.r32(.r9) }, "rdfsbase r9d");
    fails += check(&.{ 0xF3, 0x0F, 0xAE, 0xC6 }, .rdfsbase, .{ gp.r32(.rsi) }, "rdfsbase esi");
