test "x86_64 gp forms vs LLVM (2800..3138)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    const x = @import("x86_64/assembler.zig");
    const gp = @import("x86_64/gp.zig");
    var fails: u32 = 0;
    fails += check(&.{ 0x83, 0x2D, 0x00, 0x01, 0x00, 0x00, 0xFD }, .sub, .{ gp.rip(0x100, .d), @as(i64, -3) }, "sub dword ptr [rip+0x100], -3");
    fails += check(&.{ 0x81, 0xE9, 0x78, 0x56, 0x34, 0x12 }, .sub, .{ gp.r32(.rcx), @as(i64, 305419896) }, "sub ecx, 305419896");
    fails += check(&.{ 0x41, 0x81, 0xE9, 0x78, 0x56, 0x34, 0x12 }, .sub, .{ gp.r32(.r9), @as(i64, 305419896) }, "sub r9d, 305419896");
    fails += check(&.{ 0x81, 0xEE, 0x78, 0x56, 0x34, 0x12 }, .sub, .{ gp.r32(.rsi), @as(i64, 305419896) }, "sub esi, 305419896");
    fails += check(&.{ 0x83, 0xE9, 0xFD }, .sub, .{ gp.r32(.rcx), @as(i64, -3) }, "sub ecx, -3");
    fails += check(&.{ 0x41, 0x83, 0xE9, 0xFD }, .sub, .{ gp.r32(.r9), @as(i64, -3) }, "sub r9d, -3");
    fails += check(&.{ 0x83, 0xEE, 0xFD }, .sub, .{ gp.r32(.rsi), @as(i64, -3) }, "sub esi, -3");
    fails += check(&.{ 0x2B, 0x4C, 0x48, 0x10 }, .sub, .{ gp.r32(.rcx), gp.dword(x.ptrIdx(.rax, .rcx, .x2, 16)) }, "sub ecx, dword ptr [rax+rcx*2+16]");
    fails += check(&.{ 0x45, 0x2B, 0x4D, 0x00 }, .sub, .{ gp.r32(.r9), gp.dword(x.ptr(.r13, 0)) }, "sub r9d, dword ptr [r13]");
    fails += check(&.{ 0x43, 0x2B, 0xB4, 0xCC, 0x00, 0xF0, 0xFF, 0xFF }, .sub, .{ gp.r32(.rsi), gp.dword(x.ptrIdx(.r12, .r9, .x8, -0x1000)) }, "sub esi, dword ptr [r12+r9*8-4096]");
    fails += check(&.{ 0x2B, 0x0D, 0x00, 0x01, 0x00, 0x00 }, .sub, .{ gp.r32(.rcx), gp.rip(0x100, .d) }, "sub ecx, dword ptr [rip+0x100]");
    fails += check(&.{ 0x48, 0x2D, 0xBB, 0xDC, 0xFE, 0xFF }, .sub, .{ gp.r64(.rax), @as(i64, -74565) }, "sub rax, -74565");
    fails += check(&.{ 0x48, 0x81, 0x6C, 0x48, 0x10, 0xBB, 0xDC, 0xFE, 0xFF }, .sub, .{ gp.qword(x.ptrIdx(.rax, .rcx, .x2, 16)), @as(i64, -74565) }, "sub qword ptr [rax+rcx*2+16], -74565");
    fails += check(&.{ 0x49, 0x81, 0x6D, 0x00, 0xBB, 0xDC, 0xFE, 0xFF }, .sub, .{ gp.qword(x.ptr(.r13, 0)), @as(i64, -74565) }, "sub qword ptr [r13], -74565");
    fails += check(&.{ 0x4B, 0x81, 0xAC, 0xCC, 0x00, 0xF0, 0xFF, 0xFF, 0xBB, 0xDC, 0xFE, 0xFF }, .sub, .{ gp.qword(x.ptrIdx(.r12, .r9, .x8, -0x1000)), @as(i64, -74565) }, "sub qword ptr [r12+r9*8-4096], -74565");
    fails += check(&.{ 0x48, 0x81, 0x2D, 0x00, 0x01, 0x00, 0x00, 0xBB, 0xDC, 0xFE, 0xFF }, .sub, .{ gp.rip(0x100, .q), @as(i64, -74565) }, "sub qword ptr [rip+0x100], -74565");
    fails += check(&.{ 0x48, 0x83, 0x6C, 0x48, 0x10, 0xFD }, .sub, .{ gp.qword(x.ptrIdx(.rax, .rcx, .x2, 16)), @as(i64, -3) }, "sub qword ptr [rax+rcx*2+16], -3");
    fails += check(&.{ 0x49, 0x83, 0x6D, 0x00, 0xFD }, .sub, .{ gp.qword(x.ptr(.r13, 0)), @as(i64, -3) }, "sub qword ptr [r13], -3");
    fails += check(&.{ 0x4B, 0x83, 0xAC, 0xCC, 0x00, 0xF0, 0xFF, 0xFF, 0xFD }, .sub, .{ gp.qword(x.ptrIdx(.r12, .r9, .x8, -0x1000)), @as(i64, -3) }, "sub qword ptr [r12+r9*8-4096], -3");
